BEGIN;
-- Time sheets, server timers, historical rate snapshots and exactly-once invoice sources
CREATE SCHEMA erp_time_private;
REVOKE ALL ON SCHEMA erp_time_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_time_catalogs(id uuid PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,kind text NOT NULL CHECK(kind IN('project','activity')),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 160),active boolean NOT NULL DEFAULT true,customer_id uuid,rate numeric(16,2) NOT NULL DEFAULT 0 CHECK(rate>=0),description text NOT NULL DEFAULT '',UNIQUE(cafe_id,id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id));
CREATE UNIQUE INDEX erp_time_catalog_name ON public.erp_time_catalogs(cafe_id,kind,lower(name));
CREATE TABLE public.erp_time_settings(cafe_id uuid PRIMARY KEY REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,include_wages boolean NOT NULL DEFAULT false,default_billing_rate numeric(16,2) NOT NULL DEFAULT 0 CHECK(default_billing_rate>=0),default_cost_rate numeric(16,2) NOT NULL DEFAULT 0 CHECK(default_cost_rate>=0));
CREATE TABLE public.erp_time_rates(id uuid PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,worker_kind text NOT NULL CHECK(worker_kind IN('user','employee')),worker_id uuid NOT NULL,cost_rate numeric(16,2) NOT NULL CHECK(cost_rate>=0),billing_rate numeric(16,2) NOT NULL CHECK(billing_rate>=0),effective_from date NOT NULL,UNIQUE(cafe_id,worker_kind,worker_id,effective_from));
CREATE TABLE public.erp_time_batches(id uuid PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,draft_id uuid NOT NULL REFERENCES public.bf_invoice_drafts(id),customer_id uuid NOT NULL,invoice_id uuid REFERENCES public.bf_documents(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','issued','cancelled')),expected_invoice jsonb NOT NULL,total numeric(18,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),UNIQUE(cafe_id,draft_id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id));
CREATE TABLE public.erp_time_entries(id uuid PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,worker_kind text NOT NULL CHECK(worker_kind IN('user','employee')),worker_id uuid NOT NULL,worker_key uuid NOT NULL,project_id uuid NOT NULL,activity_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,CHECK(ends_at IS NULL OR ends_at>starts_at),note text NOT NULL DEFAULT '' CHECK(length(note)<=5000),billable boolean NOT NULL DEFAULT true,source_kind text NOT NULL DEFAULT 'none' CHECK(source_kind IN('none','work_order','workflow','task','contracting_project')),source_id uuid,CHECK((source_kind='none')=(source_id IS NULL)),cost_rate numeric(16,2) NOT NULL DEFAULT 0,billing_rate numeric(16,2) NOT NULL DEFAULT 0,batch_id uuid,invoice_id uuid REFERENCES public.bf_documents(id),created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cafe_id,id),FOREIGN KEY(cafe_id,project_id) REFERENCES public.erp_time_catalogs(cafe_id,id),FOREIGN KEY(cafe_id,activity_id) REFERENCES public.erp_time_catalogs(cafe_id,id),FOREIGN KEY(cafe_id,batch_id) REFERENCES public.erp_time_batches(cafe_id,id));
CREATE INDEX erp_time_entries_worker_date ON public.erp_time_entries(cafe_id,worker_key,starts_at,ends_at);
CREATE UNIQUE INDEX erp_time_one_running ON public.erp_time_entries(cafe_id,worker_key) WHERE ends_at IS NULL;
CREATE INDEX erp_time_entries_source ON public.erp_time_entries(cafe_id,source_kind,source_id);
CREATE INDEX erp_time_entries_batch ON public.erp_time_entries(cafe_id,batch_id);
CREATE TABLE public.erp_time_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL REFERENCES public.cafes(id),record_id uuid,action text NOT NULL,detail jsonb NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),at timestamptz NOT NULL DEFAULT now());
CREATE INDEX erp_time_events_cafe ON public.erp_time_events(cafe_id,at DESC);
CREATE TRIGGER erp_time_events_immutable BEFORE UPDATE OR DELETE ON public.erp_time_events FOR EACH ROW EXECUTE FUNCTION brand_finance_private.immutable();
CREATE TABLE erp_time_private.requests(cafe_id uuid NOT NULL REFERENCES public.cafes(id),request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_time_catalogs','erp_time_settings','erp_time_rates','erp_time_batches','erp_time_entries','erp_time_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END$$;
ALTER TABLE erp_time_private.requests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION erp_time_private.allowed(c uuid,a text) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$SELECT auth.uid() IS NOT NULL AND coalesce(brand_finance_private.role_for(c),'') IN('owner','manager','accountant','auditor') AND (a='read' OR brand_finance_private.role_for(c)<>'auditor') AND(a<>'settings' OR brand_finance_private.role_for(c) IN('owner','manager')) AND erp_access_private.allowed(c,'time',a)$$;
CREATE FUNCTION erp_time_private.authorize(c uuid,a text) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF NOT coalesce(erp_time_private.allowed(c,a),false) THEN RAISE EXCEPTION 'صلاحيات تتبع الوقت لا تسمح بهذه العملية' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION erp_time_private.worker(c uuid,k text,i uuid) RETURNS uuid LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE result uuid;BEGIN
 IF k='user' AND(EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=c AND user_id=i AND active) OR EXISTS(SELECT 1 FROM public.cafes WHERE id=c AND owner_user_id=i)) THEN RETURN i;END IF;
 IF k='employee' THEN SELECT coalesce(user_id,id) INTO result FROM public.erp_hr_employees WHERE cafe_id=c AND id=i AND active;END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'الموظف غير متاح لهذه العلامة' USING ERRCODE='42501';END IF;RETURN result;
END$$;
CREATE FUNCTION erp_time_private.invoice_signature(p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT jsonb_build_object('lines',(SELECT jsonb_agg(jsonb_build_object('quantity',x->'quantity','price',x->'price','productId',coalesce(x->>'productId',''),'kind',coalesce(x->>'kind','service'),'vatRate',coalesce((x->>'vatRate')::numeric,15),'taxCategory',coalesce(x->>'taxCategory','S'),'exemptionReason',coalesce(x->>'exemptionReason',''),'discount',coalesce((x->>'discount')::numeric,0),'discountKind',coalesce(x->>'discountKind','amount')) ORDER BY ordinal) FROM jsonb_array_elements(p#>'{invoice,lines}') WITH ORDINALITY e(x,ordinal)),'partyId',p#>'{invoice,partyId}','currency',coalesce(p#>>'{invoice,currency}','SAR'),'exchangeRate',coalesce((p#>>'{invoice,exchangeRate}')::numeric,1),'discountValue',coalesce((p#>>'{invoice,discountValue}')::numeric,0),'discountKind',coalesce(p#>>'{invoice,discountKind}','amount'),'taxInclusive',coalesce((p#>>'{invoice,taxInclusive}')::boolean,false),'adjustment',coalesce((p#>>'{invoice,adjustment,amount}')::numeric,0))$$;
CREATE FUNCTION erp_time_private.make_invoice(c uuid,p jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE ids uuid[];entry public.erp_time_entries%ROWTYPE;customer uuid:=(p->>'customerId')::uuid;draft uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();lines jsonb:='[]';data jsonb;grouped jsonb:='{}';descs jsonb;key text;label text;line jsonb;worker_name text;project_name text;activity_name text;hours numeric;rate numeric;tax numeric:=(p->>'taxRate')::numeric;total numeric:=0;n integer:=0;BEGIN
 PERFORM erp_time_private.authorize(c,'approve');SELECT array_agg(value::uuid) INTO ids FROM jsonb_array_elements_text(p->'ids');
 IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 200 OR cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids)x) OR NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=customer AND kind='customer' AND active) OR p->>'group' NOT IN('project','activity','worker','date') OR p->>'format' NOT IN('grouped','detailed') OR coalesce(tax,-1) NOT BETWEEN 0 AND 100 OR coalesce((p->>'defaultRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR jsonb_typeof(p->'overrideRate') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p->'description') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'description') x WHERE x NOT IN('project','activity','worker','date','note')) THEN RAISE EXCEPTION 'راجع الساعات والعميل وخيارات الفوترة';END IF;
 IF(SELECT count(*) FROM public.erp_time_entries WHERE cafe_id=c AND id=ANY(ids) AND ends_at IS NOT NULL AND billable AND batch_id IS NULL AND invoice_id IS NULL)<>cardinality(ids) THEN RAISE EXCEPTION 'الساعات قيد التشغيل أو مفوترة أو محجوزة أو غير متاحة';END IF;
 FOR entry IN SELECT * FROM public.erp_time_entries WHERE cafe_id=c AND id=ANY(ids) ORDER BY starts_at,id FOR UPDATE LOOP
  IF EXISTS(SELECT 1 FROM public.erp_time_catalogs WHERE cafe_id=c AND id=entry.project_id AND customer_id IS NOT NULL AND customer_id<>customer) THEN RAISE EXCEPTION 'العميل لا يطابق مشروع الوقت';END IF;
  IF entry.source_kind='workflow' AND NOT EXISTS(SELECT 1 FROM public.erp_workflow_records r JOIN public.erp_workflow_types t ON t.cafe_id=r.cafe_id AND t.id=r.type_id WHERE r.cafe_id=c AND r.id=entry.source_id AND 'customerId'=ANY(erp_workflow_private.fields(c,t.config,'read'))) THEN RAISE EXCEPTION 'صلاحيات حقول الدورة لا تسمح بفوترة وقتها' USING ERRCODE='42501';END IF;
  data:=erp_time_private.source(c,entry.source_kind,entry.source_id);IF nullif(data->>'customerId','')::uuid IS NOT NULL AND nullif(data->>'customerId','')::uuid<>customer THEN RAISE EXCEPTION 'العميل لا يطابق مصدر الوقت';END IF;
  rate:=CASE WHEN(p->>'overrideRate')::boolean THEN(p->>'defaultRate')::numeric ELSE coalesce(nullif(entry.billing_rate,0),(p->>'defaultRate')::numeric) END;IF rate<=0 THEN RAISE EXCEPTION 'حدد سعر ساعة موجبًا لجميع السجلات';END IF;
  SELECT name INTO project_name FROM public.erp_time_catalogs WHERE cafe_id=c AND id=entry.project_id;SELECT name INTO activity_name FROM public.erp_time_catalogs WHERE cafe_id=c AND id=entry.activity_id;
  IF entry.worker_kind='employee' THEN SELECT first_name||' '||last_name INTO worker_name FROM public.erp_hr_employees WHERE cafe_id=c AND id=entry.worker_id;ELSE SELECT name INTO worker_name FROM public.bf_staff WHERE cafe_id=c AND user_id=entry.worker_id;worker_name:=coalesce(worker_name,'المالك');END IF;
  label:=concat_ws(' — ',CASE WHEN p->'description'?'project' THEN project_name END,CASE WHEN p->'description'?'activity' THEN activity_name END,CASE WHEN p->'description'?'worker' THEN worker_name END,CASE WHEN p->'description'?'date' THEN(entry.starts_at AT TIME ZONE 'Asia/Riyadh')::date::text END,CASE WHEN p->'description'?'note' THEN nullif(entry.note,'') END);IF label='' THEN label:='ساعات عمل';END IF;
  hours:=extract(epoch FROM entry.ends_at-entry.starts_at)/3600;key:=CASE WHEN p->>'format'='detailed' THEN entry.id::text ELSE CASE p->>'group' WHEN 'project' THEN entry.project_id::text WHEN 'activity' THEN entry.activity_id::text WHEN 'worker' THEN entry.worker_kind||entry.worker_id::text ELSE(entry.starts_at AT TIME ZONE 'Asia/Riyadh')::date::text END||':'||rate::text END;
  line:=grouped->key;IF line IS NULL THEN grouped:=jsonb_set(grouped,ARRAY[key],jsonb_build_object('hours',hours,'rate',rate,'description',label));ELSE grouped:=jsonb_set(grouped,ARRAY[key],line||jsonb_build_object('hours',(line->>'hours')::numeric+hours,'description',left(line->>'description'||' | '||label,500)));END IF;
 END LOOP;
 FOR line IN SELECT value FROM jsonb_each(grouped) LOOP n:=n+1;IF n>100 THEN RAISE EXCEPTION 'الحد الأقصى مائة بند في الفاتورة استخدم التجميع أو حدد ساعات أقل';END IF;hours:=round((line->>'hours')::numeric,6);rate:=(line->>'rate')::numeric;total:=total+round(hours*rate,2)+round(round(hours*rate,2)*tax/100,2);lines:=lines||jsonb_build_array(jsonb_build_object('key',n,'productId','','name',left(line->>'description',160),'kind','service','quantity',hours,'price',rate,'vatRate',tax,'taxCategory',CASE WHEN tax=0 THEN 'O' ELSE 'S' END,'exemptionReason',coalesce(p->>'taxReason','')));END LOOP;
 data:=jsonb_build_object('invoice',jsonb_build_object('lines',lines,'warehouseId','','partyId',customer,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note','فاتورة ساعات عمل','currency','SAR','exchangeRate',1),'issuer',jsonb_build_object('name','','address','','vatNumber',''),'supplyDate',current_date,'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
 PERFORM public.brand_finance_save_invoice_draft(c,draft,0,data);INSERT INTO public.erp_time_batches(id,cafe_id,draft_id,customer_id,expected_invoice,total) VALUES(batch,c,draft,customer,erp_time_private.invoice_signature(data),total);UPDATE public.erp_time_entries SET batch_id=batch,revision=revision+1 WHERE cafe_id=c AND id=ANY(ids);
 RETURN jsonb_build_object('id',batch,'draftId',draft);
END$$;
CREATE FUNCTION erp_time_private.source(c uuid,k text,i uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE data jsonb;r public.erp_workflow_records%ROWTYPE;BEGIN
 IF k='none' AND i IS NULL THEN RETURN NULL;END IF;
 IF k='work_order' THEN PERFORM erp_work_private.authorize(c);SELECT jsonb_build_object('name',title,'customerId',customer_id) INTO data FROM public.erp_work_orders WHERE cafe_id=c AND id=i;
 ELSIF k='workflow' THEN r:=erp_workflow_private.assert_record(c,i);SELECT erp_workflow_private.mask(c,r,config) INTO data FROM public.erp_workflow_types WHERE cafe_id=c AND id=r.type_id;data:=jsonb_build_object('name',coalesce(data->>'title','دورة عمل'),'customerId',data->'customerId','href','/dashboard/system/workflows/'||r.type_id||'/'||r.id);
 ELSIF k='task' THEN PERFORM erp_access_private.assert_allowed(c,'tasks','read');SELECT jsonb_build_object('name',title,'customerId',CASE WHEN target_kind='customer' THEN target_id END) INTO data FROM public.erp_tasks WHERE cafe_id=c AND id=i;
 ELSIF k='contracting_project' THEN PERFORM erp_access_private.assert_allowed(c,'contracting','read');SELECT jsonb_build_object('name',title,'customerId',customer_id) INTO data FROM public.erp_contracting_documents WHERE cafe_id=c AND id=i AND kind='project';END IF;
 IF data IS NULL THEN RAISE EXCEPTION 'السجل المرتبط غير متاح' USING ERRCODE='42501';END IF;RETURN data;
END$$;
CREATE FUNCTION erp_time_private.save_entry(c uuid,p jsonb,running boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$
DECLARE eid uuid:=(p->>'id')::uuid;old public.erp_time_entries%ROWTYPE;worker uuid;begin_at timestamptz;end_at timestamptz;cost numeric;rate numeric;project public.erp_time_catalogs%ROWTYPE;source jsonb;BEGIN
 SELECT * INTO old FROM public.erp_time_entries WHERE cafe_id=c AND id=eid FOR UPDATE;
 PERFORM erp_time_private.authorize(c,CASE WHEN old.id IS NULL THEN 'create' ELSE 'update' END);
 IF eid IS NULL OR coalesce(old.revision,0) IS DISTINCT FROM coalesce((p->>'revision')::integer,0) THEN RAISE EXCEPTION 'سجل الوقت تغير' USING ERRCODE='40001';END IF;
 IF old.batch_id IS NOT NULL OR old.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'الساعات محجوزة لفاتورة ولا يمكن تغييرها';END IF;
 IF running AND old.id IS NOT NULL THEN RAISE EXCEPTION 'المؤقت مسجل مسبقًا';END IF;
 worker:=erp_time_private.worker(c,p->>'workerKind',(p->>'workerId')::uuid);begin_at:=CASE WHEN running THEN clock_timestamp() ELSE (p->>'start')::timestamptz END;end_at:=CASE WHEN running THEN NULL ELSE(p->>'end')::timestamptz END;
 IF begin_at IS NULL OR NOT running AND(end_at IS NULL OR end_at<=begin_at OR end_at-begin_at>interval '24 hours') OR begin_at>clock_timestamp()+interval '366 days' OR length(coalesce(p->>'note',''))>5000 OR jsonb_typeof(p->'billable') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع الفترة والمدة وبيانات الوقت';END IF;
 SELECT * INTO project FROM public.erp_time_catalogs WHERE cafe_id=c AND id=(p->>'projectId')::uuid AND kind='project' AND active;
 IF project.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.erp_time_catalogs WHERE cafe_id=c AND id=(p->>'activityId')::uuid AND kind='activity' AND active) THEN RAISE EXCEPTION 'اختر مشروعًا ونشاطًا نشطين';END IF;
 source:=erp_time_private.source(c,p->>'sourceKind',nullif(p->>'sourceId','')::uuid);
 IF project.customer_id IS NOT NULL AND nullif(source->>'customerId','')::uuid IS NOT NULL AND project.customer_id<>nullif(source->>'customerId','')::uuid THEN RAISE EXCEPTION 'عميل المشروع لا يطابق السجل المرتبط';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=c AND worker_key=worker AND id<>eid AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(begin_at,end_at,'[)')) THEN RAISE EXCEPTION 'توجد ساعات متداخلة للموظف نفسه' USING ERRCODE='23P01';END IF;
 SELECT cost_rate,billing_rate INTO cost,rate FROM public.erp_time_rates WHERE cafe_id=c AND worker_kind=p->>'workerKind' AND worker_id=(p->>'workerId')::uuid AND effective_from<=(begin_at AT TIME ZONE 'Asia/Riyadh')::date ORDER BY effective_from DESC LIMIT 1;
 cost:=coalesce(cost,(SELECT default_cost_rate FROM public.erp_time_settings WHERE cafe_id=c),0);rate:=coalesce(nullif(project.rate,0),nullif(rate,0),(SELECT default_billing_rate FROM public.erp_time_settings WHERE cafe_id=c),0);
 INSERT INTO public.erp_time_entries(id,cafe_id,worker_kind,worker_id,worker_key,project_id,activity_id,starts_at,ends_at,note,billable,source_kind,source_id,cost_rate,billing_rate,created_by) VALUES(eid,c,p->>'workerKind',(p->>'workerId')::uuid,worker,project.id,(p->>'activityId')::uuid,begin_at,end_at,coalesce(p->>'note',''),(p->>'billable')::boolean,p->>'sourceKind',nullif(p->>'sourceId','')::uuid,cost,rate,auth.uid()) ON CONFLICT(id) DO UPDATE SET revision=erp_time_entries.revision+1,worker_kind=excluded.worker_kind,worker_id=excluded.worker_id,worker_key=excluded.worker_key,project_id=excluded.project_id,activity_id=excluded.activity_id,starts_at=excluded.starts_at,ends_at=excluded.ends_at,note=excluded.note,billable=excluded.billable,source_kind=excluded.source_kind,source_id=excluded.source_id,cost_rate=excluded.cost_rate,billing_rate=excluded.billing_rate WHERE erp_time_entries.cafe_id=c;
 IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;RETURN eid;
END$$;
CREATE FUNCTION public.erp_time_cost_report(p_cafe_id uuid,p_from date,p_to date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE enabled boolean;BEGIN
 PERFORM erp_time_private.authorize(p_cafe_id,'read');IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>3660 THEN RAISE EXCEPTION 'فترة التقرير غير صالحة';END IF;
 SELECT include_wages INTO enabled FROM public.erp_time_settings WHERE cafe_id=p_cafe_id;
 RETURN jsonb_build_object('enabled',coalesce(enabled,false),'currency','SAR','classification','accrued_time_cost','cashPaid',0,'from',p_from,'to',p_to,'total',CASE WHEN enabled THEN coalesce((SELECT sum(round(extract(epoch FROM least(ends_at,(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest(starts_at,p_from::timestamp AT TIME ZONE 'Asia/Riyadh'))/3600*cost_rate,2)) FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND ends_at IS NOT NULL AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(p_from::timestamp AT TIME ZONE 'Asia/Riyadh',(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh','[)')),0) ELSE 0 END,'rows',CASE WHEN enabled THEN coalesce((SELECT jsonb_agg(jsonb_build_object('entryId',id,'workerKind',worker_kind,'workerId',worker_id,'projectId',project_id,'sourceKind',source_kind,'sourceId',source_id,'seconds',extract(epoch FROM least(ends_at,(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest(starts_at,p_from::timestamp AT TIME ZONE 'Asia/Riyadh')),'hourlyRate',cost_rate,'amount',round(extract(epoch FROM least(ends_at,(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest(starts_at,p_from::timestamp AT TIME ZONE 'Asia/Riyadh'))/3600*cost_rate,2))) FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND ends_at IS NOT NULL AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(p_from::timestamp AT TIME ZONE 'Asia/Riyadh',(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh','[)')),'[]') ELSE '[]'::jsonb END);
END$$;
CREATE FUNCTION public.erp_time_read(p_cafe_id uuid,p_from date DEFAULT NULL,p_to date DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE sources jsonb:='[]';source_row record;source_data jsonb;BEGIN
 PERFORM erp_time_private.authorize(p_cafe_id,'read');
 IF(p_from IS NULL)<>(p_to IS NULL) OR p_to<p_from OR p_to-p_from>3660 THEN RAISE EXCEPTION 'فترة العرض غير صالحة';END IF;
 FOR source_row IN SELECT id,'work_order' kind FROM public.erp_work_orders WHERE cafe_id=p_cafe_id UNION ALL SELECT id,'workflow' FROM public.erp_workflow_records WHERE cafe_id=p_cafe_id UNION ALL SELECT id,'task' FROM public.erp_tasks WHERE cafe_id=p_cafe_id UNION ALL SELECT id,'contracting_project' FROM public.erp_contracting_documents WHERE cafe_id=p_cafe_id AND kind='project' LIMIT 2000 LOOP
  BEGIN source_data:=erp_time_private.source(p_cafe_id,source_row.kind,source_row.id);sources:=sources||jsonb_build_array(source_data||jsonb_build_object('id',source_row.id,'kind',source_row.kind));EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 END LOOP;
 RETURN jsonb_build_object('serverNow',clock_timestamp(),'entries',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'revision',e.revision,'workerKind',e.worker_kind,'workerId',e.worker_id,'workerName',CASE WHEN e.worker_kind='employee' THEN coalesce(h.first_name||' '||h.last_name,'موظف') ELSE coalesce(s.name,'المالك') END,'projectId',e.project_id,'projectName',p.name,'activityId',e.activity_id,'activityName',a.name,'customerId',p.customer_id,'start',e.starts_at,'end',e.ends_at,'seconds',extract(epoch FROM coalesce(e.ends_at,clock_timestamp())-e.starts_at)::integer,'note',e.note,'billable',e.billable,'sourceKind',e.source_kind,'sourceId',e.source_id,'costRate',e.cost_rate,'billingRate',e.billing_rate,'batchId',e.batch_id,'invoiceId',e.invoice_id,'createdAt',e.created_at) ORDER BY e.starts_at DESC) FROM public.erp_time_entries e JOIN public.erp_time_catalogs p ON p.cafe_id=e.cafe_id AND p.id=e.project_id JOIN public.erp_time_catalogs a ON a.cafe_id=e.cafe_id AND a.id=e.activity_id LEFT JOIN public.bf_staff s ON s.cafe_id=e.cafe_id AND s.user_id=e.worker_id AND e.worker_kind='user' LEFT JOIN public.erp_hr_employees h ON h.cafe_id=e.cafe_id AND h.id=e.worker_id AND e.worker_kind='employee' WHERE e.cafe_id=p_cafe_id AND (p_from IS NULL OR e.ends_at IS NULL OR e.starts_at<(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh' AND e.ends_at>p_from::timestamp AT TIME ZONE 'Asia/Riyadh')),'[]'),
 'catalogs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'kind',kind,'name',name,'active',active,'customerId',customer_id,'rate',rate,'description',description) ORDER BY kind,name) FROM public.erp_time_catalogs WHERE cafe_id=p_cafe_id),'[]'),
 'rates',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'workerKind',worker_kind,'workerId',worker_id,'costRate',cost_rate,'billingRate',billing_rate,'effectiveFrom',effective_from) ORDER BY effective_from DESC) FROM public.erp_time_rates WHERE cafe_id=p_cafe_id),'[]'),
 'workers',coalesce((SELECT jsonb_agg(w) FROM(SELECT id,'employee' kind,first_name||' '||last_name name,active,user_id AS "userId" FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id UNION ALL SELECT user_id,'user',name,active,user_id FROM public.bf_staff s WHERE cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND user_id=s.user_id AND active) UNION ALL SELECT owner_user_id,'user','المالك',true,owner_user_id FROM public.cafes c WHERE id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=c.id AND user_id=c.owner_user_id) AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=c.id AND user_id=c.owner_user_id AND active))w),'[]'),
 'batches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'draftId',draft_id,'invoiceId',invoice_id,'status',status,'createdAt',created_at,'total',total) ORDER BY created_at DESC) FROM public.erp_time_batches WHERE cafe_id=p_cafe_id),'[]'),
 'settings',coalesce((SELECT jsonb_build_object('revision',revision,'includeWages',include_wages,'defaultBillingRate',default_billing_rate,'defaultCostRate',default_cost_rate) FROM public.erp_time_settings WHERE cafe_id=p_cafe_id),' {"revision":0,"includeWages":false,"defaultBillingRate":0,"defaultCostRate":0}'::jsonb),'sources',sources,
 'events',coalesce((SELECT jsonb_agg(x) FROM(SELECT id,action,at,record_id AS "recordId" FROM public.erp_time_events WHERE cafe_id=p_cafe_id ORDER BY at DESC LIMIT 500)x),'[]'),'canCreate',erp_time_private.allowed(p_cafe_id,'create'),'canUpdate',erp_time_private.allowed(p_cafe_id,'update'),'canDelete',erp_time_private.allowed(p_cafe_id,'delete'),'canApprove',erp_time_private.allowed(p_cafe_id,'approve'),'canConfigure',erp_time_private.allowed(p_cafe_id,'settings'));
END$$;
CREATE FUNCTION public.erp_time_write(p_cafe_id uuid,p_action text,p_payload jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
<<time_write>>
DECLARE rid uuid:=nullif(p_payload->>'id','')::uuid;rev integer:=coalesce((p_payload->>'revision')::integer,0);previous erp_time_private.requests%ROWTYPE;entry public.erp_time_entries%ROWTYPE;batch public.erp_time_batches%ROWTYPE;old_revision integer;result jsonb;row jsonb;ids uuid[]:='{}';end_at timestamptz;action_name text;BEGIN
 IF auth.uid() IS NULL OR p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>1000000 THEN RAISE EXCEPTION 'طلب تتبع الوقت غير صالح';END IF;
 action_name:=CASE WHEN p_action IN('settings','catalog','delete_catalog','rate','delete_rate') THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN p_action IN('invoice','cancel_invoice') THEN 'approve' WHEN p_action IN('start','import') OR p_action='entry' AND rev=0 THEN 'create' ELSE 'update' END;PERFORM erp_time_private.authorize(p_cafe_id,action_name);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));SELECT * INTO previous FROM erp_time_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>p_action OR previous.payload<>p_payload THEN RAISE EXCEPTION 'مفتاح الطلب مستخدم لعملية أخرى' USING ERRCODE='22023';END IF;RETURN previous.result;END IF;result:=jsonb_build_object('id',rid);
 IF p_action IN('entry','start') THEN rid:=erp_time_private.save_entry(p_cafe_id,p_payload,p_action='start');result:=jsonb_build_object('id',rid);
 ELSIF p_action='import' THEN
  IF jsonb_typeof(p_payload->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'rows') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'الحد الأقصى مائة سجل في الاستيراد';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(p_payload->'rows') LOOP IF coalesce((row->>'revision')::integer,0)<>0 THEN RAISE EXCEPTION 'الاستيراد يضيف سجلات جديدة فقط';END IF;ids:=array_append(ids,erp_time_private.save_entry(p_cafe_id,row,false));END LOOP;result:=jsonb_build_object('ids',ids,'count',cardinality(ids));
 ELSIF p_action IN('stop','delete') THEN
  SELECT * INTO entry FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF entry.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'السجل تغير أو غير متاح' USING ERRCODE='40001';END IF;
  IF entry.batch_id IS NOT NULL OR entry.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'الساعات محجوزة أو مفوترة';END IF;
  IF p_action='delete' THEN DELETE FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND id=rid;ELSE
   IF entry.ends_at IS NOT NULL THEN RAISE EXCEPTION 'المؤقت متوقف بالفعل';END IF;end_at:=clock_timestamp();IF end_at<=entry.starts_at THEN RAISE EXCEPTION 'انتظر بداية المؤقت';END IF;
   UPDATE public.erp_time_entries SET ends_at=end_at,revision=revision+1 WHERE cafe_id=p_cafe_id AND id=rid;
  END IF;
 ELSIF p_action='catalog' THEN
  SELECT revision INTO old_revision FROM public.erp_time_catalogs WHERE cafe_id=p_cafe_id AND id=rid;IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'التعريف تغير' USING ERRCODE='40001';END IF;
  IF rid IS NULL OR coalesce(p_payload->>'kind','') NOT IN('project','activity') OR length(btrim(coalesce(p_payload->>'name',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean' OR coalesce((p_payload->>'rate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR length(coalesce(p_payload->>'description',''))>2000 THEN RAISE EXCEPTION 'راجع بيانات المشروع أو النشاط';END IF;
  IF nullif(p_payload->>'customerId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=(p_payload->>'customerId')::uuid AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_time_catalogs c WHERE cafe_id=p_cafe_id AND id=rid AND (kind<>p_payload->>'kind' OR customer_id IS DISTINCT FROM nullif(p_payload->>'customerId','')::uuid)) AND EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND(project_id=rid OR activity_id=rid)) THEN RAISE EXCEPTION 'لا تغير نوع التعريف أو العميل بعد تسجيل الوقت';END IF;
  INSERT INTO public.erp_time_catalogs(id,cafe_id,revision,kind,name,active,customer_id,rate,description) VALUES(rid,p_cafe_id,rev+1,p_payload->>'kind',btrim(p_payload->>'name'),(p_payload->>'active')::boolean,nullif(p_payload->>'customerId','')::uuid,(p_payload->>'rate')::numeric,coalesce(p_payload->>'description','')) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,kind=excluded.kind,name=excluded.name,active=excluded.active,customer_id=excluded.customer_id,rate=excluded.rate,description=excluded.description WHERE erp_time_catalogs.cafe_id=p_cafe_id;IF NOT FOUND THEN RAISE EXCEPTION 'التعريف غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_action='delete_catalog' THEN DELETE FROM public.erp_time_catalogs WHERE cafe_id=p_cafe_id AND id=rid AND revision=rev;IF NOT FOUND THEN RAISE EXCEPTION 'التعريف تغير' USING ERRCODE='40001';END IF;
 ELSIF p_action='settings' THEN
  SELECT revision INTO old_revision FROM public.erp_time_settings WHERE cafe_id=p_cafe_id;IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'الإعدادات تغيرت' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_payload->'includeWages') IS DISTINCT FROM 'boolean' OR coalesce((p_payload->>'defaultCostRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR coalesce((p_payload->>'defaultBillingRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 THEN RAISE EXCEPTION 'راجع إعدادات التكلفة والأسعار';END IF;
  INSERT INTO public.erp_time_settings VALUES(p_cafe_id,rev+1,(p_payload->>'includeWages')::boolean,(p_payload->>'defaultBillingRate')::numeric,(p_payload->>'defaultCostRate')::numeric) ON CONFLICT(cafe_id) DO UPDATE SET revision=excluded.revision,include_wages=excluded.include_wages,default_billing_rate=excluded.default_billing_rate,default_cost_rate=excluded.default_cost_rate;
 ELSIF p_action='rate' THEN
  PERFORM erp_time_private.worker(p_cafe_id,p_payload->>'workerKind',(p_payload->>'workerId')::uuid);SELECT revision INTO old_revision FROM public.erp_time_rates WHERE cafe_id=p_cafe_id AND id=rid;IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'سعر الساعة تغير' USING ERRCODE='40001';END IF;
  IF rid IS NULL OR coalesce((p_payload->>'costRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR coalesce((p_payload->>'billingRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR nullif(p_payload->>'effectiveFrom','')::date IS NULL THEN RAISE EXCEPTION 'راجع معدل الساعة وتاريخ السريان';END IF;
  INSERT INTO public.erp_time_rates(id,cafe_id,revision,worker_kind,worker_id,cost_rate,billing_rate,effective_from) VALUES(rid,p_cafe_id,rev+1,p_payload->>'workerKind',(p_payload->>'workerId')::uuid,(p_payload->>'costRate')::numeric,(p_payload->>'billingRate')::numeric,(p_payload->>'effectiveFrom')::date) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,worker_kind=excluded.worker_kind,worker_id=excluded.worker_id,cost_rate=excluded.cost_rate,billing_rate=excluded.billing_rate,effective_from=excluded.effective_from WHERE erp_time_rates.cafe_id=p_cafe_id;IF NOT FOUND THEN RAISE EXCEPTION 'السعر غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_action='delete_rate' THEN DELETE FROM public.erp_time_rates WHERE cafe_id=p_cafe_id AND id=rid AND revision=rev;IF NOT FOUND THEN RAISE EXCEPTION 'السعر تغير' USING ERRCODE='40001';END IF;
 ELSIF p_action='invoice' THEN result:=erp_time_private.make_invoice(p_cafe_id,p_payload);rid:=(result->>'id')::uuid;
 ELSIF p_action='cancel_invoice' THEN
  SELECT * INTO batch FROM public.erp_time_batches WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF batch.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'دفعة الفوترة تغيرت' USING ERRCODE='40001';END IF;
  IF batch.status<>'draft' OR batch.invoice_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=batch.draft_id) THEN RAISE EXCEPTION 'الفاتورة صادرة ولا يمكن تحرير ساعاتها';END IF;
  UPDATE public.erp_time_entries SET batch_id=NULL,revision=revision+1 WHERE cafe_id=p_cafe_id AND batch_id=rid;UPDATE public.erp_time_batches SET status='cancelled',revision=revision+1 WHERE cafe_id=p_cafe_id AND id=rid;
 ELSE RAISE EXCEPTION 'إجراء تتبع الوقت غير متاح';END IF;
 INSERT INTO public.erp_time_events(cafe_id,record_id,action,detail,actor) VALUES(p_cafe_id,rid,p_action,p_payload,auth.uid());INSERT INTO erp_time_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END$$;
CREATE FUNCTION erp_time_private.issue_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE b public.erp_time_batches%ROWTYPE;data jsonb;BEGIN
 SELECT * INTO b FROM public.erp_time_batches WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 PERFORM erp_time_private.authorize(NEW.cafe_id,'approve');IF b.status='issued' AND b.invoice_id=NEW.document_id THEN RETURN NEW;END IF;
 IF b.status<>'draft' OR b.invoice_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=NEW.cafe_id AND batch_id=b.id AND invoice_id IS NULL) THEN RAISE EXCEPTION 'دفعة الساعات ملغاة أو مفوترة مسبقًا' USING ERRCODE='22023';END IF;
 SELECT payload INTO data FROM public.bf_invoice_drafts WHERE cafe_id=NEW.cafe_id AND id=NEW.draft_id;
 IF erp_time_private.invoice_signature(data) IS DISTINCT FROM b.expected_invoice THEN RAISE EXCEPTION 'بنود الساعات أو العميل تغيرت ألغ المسودة وأنشئها من الساعات مجددًا' USING ERRCODE='22023';END IF;
 UPDATE public.erp_time_entries SET invoice_id=NEW.document_id,revision=revision+1 WHERE cafe_id=NEW.cafe_id AND batch_id=b.id;UPDATE public.erp_time_batches SET invoice_id=NEW.document_id,status='issued',revision=revision+1 WHERE cafe_id=NEW.cafe_id AND id=b.id;
 INSERT INTO public.erp_time_events(cafe_id,record_id,action,detail,actor) VALUES(NEW.cafe_id,b.id,'invoice_issued',jsonb_build_object('invoiceId',NEW.document_id),auth.uid());RETURN NEW;
END$$;
CREATE TRIGGER erp_time_invoice_guard BEFORE INSERT OR UPDATE ON public.bf_company_invoices FOR EACH ROW EXECUTE FUNCTION erp_time_private.issue_guard();
CREATE FUNCTION erp_time_private.source_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN
 IF TG_TABLE_NAME='bf_documents' THEN IF EXISTS(SELECT 1 FROM public.erp_time_batches WHERE cafe_id=OLD.cafe_id AND invoice_id=OLD.id) AND(TG_OP='DELETE' OR OLD.party_id IS DISTINCT FROM NEW.party_id OR OLD.total IS DISTINCT FROM NEW.total) THEN RAISE EXCEPTION 'فاتورة ساعات العمل لا تعدل خارج مسار التصحيح المالي';END IF;
 ELSE IF EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=OLD.cafe_id AND source_id=OLD.id AND source_kind=TG_ARGV[0]) THEN RAISE EXCEPTION 'السجل مرتبط بساعات عمل';END IF;END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END$$;
CREATE TRIGGER erp_time_invoice_source_guard BEFORE UPDATE OR DELETE ON public.bf_documents FOR EACH ROW EXECUTE FUNCTION erp_time_private.source_guard();
CREATE TRIGGER erp_time_source_guard BEFORE DELETE ON public.erp_work_orders FOR EACH ROW EXECUTE FUNCTION erp_time_private.source_guard('work_order');
CREATE TRIGGER erp_time_source_guard BEFORE DELETE ON public.erp_workflow_records FOR EACH ROW EXECUTE FUNCTION erp_time_private.source_guard('workflow');
CREATE TRIGGER erp_time_source_guard BEFORE DELETE ON public.erp_tasks FOR EACH ROW EXECUTE FUNCTION erp_time_private.source_guard('task');
CREATE TRIGGER erp_time_source_guard BEFORE DELETE ON public.erp_contracting_documents FOR EACH ROW EXECUTE FUNCTION erp_time_private.source_guard('contracting_project');
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_time_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_time_read(uuid,date,date),public.erp_time_write(uuid,text,jsonb,uuid),public.erp_time_cost_report(uuid,date,date) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.erp_time_read(uuid,date,date),public.erp_time_write(uuid,text,jsonb,uuid),public.erp_time_cost_report(uuid,date,date) TO authenticated;
SELECT erp_access_private.install_guard('erp_time_read','time','PERFORM erp_access_private.assert_allowed(p_cafe_id,''time'',''read'');');
SELECT erp_access_private.install_guard('erp_time_cost_report','time','PERFORM erp_access_private.assert_allowed(p_cafe_id,''time'',''read'');');
SELECT erp_access_private.install_guard('erp_time_write','time','PERFORM erp_access_private.assert_allowed(p_cafe_id,''time'',CASE WHEN p_action IN(''settings'',''catalog'',''delete_catalog'',''rate'',''delete_rate'') THEN ''settings'' WHEN p_action=''delete'' THEN ''delete'' WHEN p_action IN(''invoice'',''cancel_invoice'') THEN ''approve'' WHEN p_action IN(''start'',''import'') OR p_action=''entry'' AND coalesce((p_payload->>''revision'')::integer,0)=0 THEN ''create'' ELSE ''update'' END);');
NOTIFY pgrst,'reload schema';
COMMIT;
